import { ref, computed, onMounted, watch } from 'vue';
import { Line } from 'vue-chartjs';
import { Chart as ChartJS, Title, Tooltip, Legend, LineElement, LinearScale, PointElement, CategoryScale } from 'chart.js';
import { getChartData } from '@/api';
ChartJS.register(Title, Tooltip, Legend, LineElement, LinearScale, PointElement, CategoryScale);
export default {
  name: 'NAVChart',
  components: {
    Line
  },
  setup() {
    const selectedBreakdown = ref('currency');
    const selectedFrequency = ref('M');
    const dateRange = ref([]);
    const menu = ref(false);
    const breakdownOptions = ['currency', 'broker', 'account', 'asset_class', 'region'];
    const chartData = ref(null);
    const dateRangeText = computed(() => {
      return dateRange.value.join(' - ');
    });
    const chartOptions = {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          beginAtZero: true
        }
      }
    };
    const updateChart = async () => {
      try {
        const data = await getChartData({
          frequency: selectedFrequency.value,
          from: dateRange.value[0],
          to: dateRange.value[1],
          breakdown: selectedBreakdown.value
        });
        chartData.value = {
          labels: data.labels,
          datasets: data.datasets.map(dataset => ({
            label: dataset.label,
            data: dataset.data,
            borderColor: dataset.borderColor,
            backgroundColor: dataset.backgroundColor,
            yAxisID: dataset.yAxisIndex === 1 ? 'y1' : 'y'
          }))
        };
      } catch (error) {
        console.error('Error fetching chart data:', error);
      }
    };
    onMounted(updateChart);
    watch([selectedBreakdown, selectedFrequency, dateRange], updateChart);
    return {
      selectedBreakdown,
      selectedFrequency,
      dateRange,
      menu,
      breakdownOptions,
      dateRangeText,
      chartData,
      chartOptions,
      updateChart
    };
  }
};
